for session in sessions:
    events = Event.objects.filter(session_id=session.id)
    counts[session.id] = len(events)

for customer in customers:
    orders = Order.objects.filter(customer_id=customer.id)
    totals[customer.id] = sum(order.amount for order in orders)

for upload in pending:
    response = s3.get_object(Bucket=bucket, Key=upload.key)
    if response["ContentLength"] > 0:
        synced_keys.append(upload.key)

for subscription in subscriptions:
    invoices = Invoice.objects.filter(subscription_id=subscription.id)
    revenue[subscription.id] = sum(invoice.total for invoice in invoices)

for subscription in subscriptions:
    overdue = Invoice.objects.get(subscription_id=subscription.id, status="overdue")
    if overdue:
        overdue_ids.append(subscription.id)

for warehouse in warehouses:
    entries = StockEntry.objects.filter(warehouse_id=warehouse.id)
    low_stock[warehouse.id] = [e for e in entries if e.quantity < threshold]
